class Solution
{
public:
    bool validWordAbbreviation(string word, string abbr)
    {
        int i = 0, j = 0;
        while (j < (int)abbr.size())
        {
            if (isdigit(abbr[j]))
            {
                if (abbr[j] == '0') return false;
                long long skip = 0;
                while (j < (int)abbr.size() && isdigit(abbr[j]))
                {
                    skip = skip * 10 + (abbr[j++] - '0');
                    if (skip > (int)word.size()) return false;
                }
                i += skip;
                if (i > (int)word.size()) return false;
            } else
            {
                if (i >= (int)word.size() || word[i] != abbr[j])
                {
                    return false;
                }
                ++i;
                ++j;
            }
        }
        return i == (int)word.size();
    }
};
